// Growth plans for named Telangana businesses, by business, industry and city.
// Generated by scripts/proposals.py from a public homepage check of each business.
// These businesses are NOT clients; every page says so and offers correction or removal.
import data from "./proposals.json";
import companies from "./companies.json";

export type Proposal = {
  slug: string;
  name: string;
  city: string;
  industry: string;
  site: string;
  checked: string; // ISO date of the homepage check
  date: string; // ISO date the plan was written
  facts: { label: string; ok: boolean }[];
  voice: string[];
  stack: string[];
  steps: string[];
};

// Spelling variants from the source lists, mapped to one city name.
const CITY_FIX: Record<string, string> = {
  Secunderbad: "Secunderabad",
  Rangareddy: "Ranga Reddy",
  "Medal District": "Medak",
  "Mahabub Nagar": "Mahabubnagar",
  Patancheruvu: "Patancheru",
};

// Every plan (owner, 12 Nov 2026; industries re-checked by scripts/reclassify_proposals.py).
// They name real businesses, so they stay reachable by link for sales but are noindex and out of the sitemap.
export const PROPOSALS: Proposal[] = (data as Proposal[]).map((p) => ({ ...p, city: CITY_FIX[p.city] ?? p.city }));

export const getProposal = (slug: string) => PROPOSALS.find((p) => p.slug === slug);

const slugify = (s: string) => s.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

// Newly registered companies (scripts/companies.py, from the MCA/GST leads sheet): name, industry,
// district, activity and registration month only. Rendered by one client page, /proposals/company?c=.
export type Company = { slug: string; name: string; industry: string; city: string; activity: string; registered: string };
export const COMPANIES = companies as Company[];
export const companyHref = (slug: string) => `/proposals/company?c=${slug}`;

const uniq = (k: "industry" | "city") => [...new Set([...PROPOSALS, ...COMPANIES].map((p) => p[k]))].sort();
export const proposalIndustries = () => uniq("industry");
export const proposalCities = () => uniq("city");
export const industrySlug = slugify;
export const citySlug = slugify;
export const industryBySlug = (s: string) => proposalIndustries().find((i) => slugify(i) === s);
export const cityBySlug = (s: string) => proposalCities().find((c) => slugify(c) === s);
